Let ${\mathcal{J}}$ be a translation invariant GC structure on $V$ of even cotype. 
        There exist $B\in\scalebox{1.2}{$\wedge$}^2 V^*, \beta\in \scalebox{1.2}{$\wedge$}^2 V$ and $J\in\mathcal C_V$, such that 
        \[{\mathcal{J}} = 
e^{\beta }

e^{B }
{\mathcal{J}}_J 
e^{-B }

e^{-\beta }
.\]

Let ${\mathcal{J}}$ be a translation-invariant GC structure on $V/\Gamma$ of even cotype. Choose $I$, $\beta$ and $B$ such that 
${\mathcal{J}} =
e^{\beta }

e^{B }
 {\mathcal{J}}_I 
e^{-B}

e^{-\beta}
$.
The \emph{derived category} of ${\mathcal{J}}$ is defined as 
\[ {\mathcal{D}}({\mathcal{J}}) = {\mathcal{P}}_{\mathbf{A}(I,\beta,B)}. \] 
If ${\mathcal{J}}$ is of odd cotype we let ${\mathcal{J}}'$ be the GC structure obtained by performing T-duality relative to any circle.
We define ${\mathcal{D}}({\mathcal{J}}) := {\mathcal{D}}({\mathcal{J}}')$.

Given a torus with translation invariant $B$-symplectic form $\omega + \mathbf{i} B$ and associated GC structure ${\mathcal{J}}_{\omega+\mathbf{i} B}=  
e^{B}
{\mathcal{J}}_\omega 
e^{-B}
$ its Fukaya category is given by the derived category of the mirror of ${\mathcal{J}}_{\omega + \mathbf{i} B}$.

Let $M$ be a smooth manifold. A \emph{Courant algebroid} over $M$ is a vector bundle $E\to M$ together with a non-degenerate scalar product $\langle\cdot,\cdot\rangle\in\Gamma(\operatorname{Sym}^2E^*)$, a bilinear bracket $[\cdot,\cdot]\colon \Gamma(E)\times \Gamma(E)\to\Gamma(E)$ and a bundle map $\rho\colon E\to TM$, called the \emph{anchor}, such that for all $u,v,w\in\Gamma(E)$ the following holds:
    \begin{itemize}
        \item $[u,[v,w]]  = [[u,v],w]+[v,[u,w]]$,
        \item $\rho(u)\langle v,w\rangle = \langle [u,v],w\rangle+\langle v,[u,w]\rangle$,
        \item $\langle [u,v]+[v,u],w\rangle = \rho(w)\langle u,v\rangle$. \hfill \qedhere
    \end{itemize}

\label{remark:AdBbeta}
We now explicitly describe certain kinds of symmetry transformations that act on $\mathcal{GC}_V$. Let 
\[
    \mathcal{J} = \begin{pmatrix} A & \pi \\ \omega  & -A^* \end{pmatrix}\in \mathcal{GC}_V,
\]
where $A\in\operatorname{End}(V), \omega  \in \scalebox{1.2}{$\wedge$}^2V^*, \pi \in\scalebox{1.2}{$\wedge$}^2V$. 
\begin{enumerate}
    \item We have already encountered $B$-field transformations. To a $2$-form $B\in\scalebox{1.2}{$\wedge$}^2V^*$ we associate the element 
    \[

e^{B }
 = \begin{pmatrix}
        1 & 0 \\ B & 1
    \end{pmatrix}\in\mathrm{O}(\mathbb{V}),
    \]
    which acts on ${\mathcal{J}}$ by 
    \[

e^{B }
{\mathcal{J}}  
e^{-B }
= \begin{pmatrix}
        A-\pi  B  & \pi  \\ B  A+A^*B +\omega -B \pi  B  & B \pi -A^*
        \end{pmatrix}.
    \]
    \item We shall also encounter $\beta$-transformations. To a bivector $\beta\in\scalebox{1.2}{$\wedge$}^2V$ we associate the element 
    \[

e^{\beta }
 = \begin{pmatrix}
        1 & \beta \\ 0 & 1
    \end{pmatrix}\in\mathrm{O}(\mathbb{V}),
    \]
    which acts on  ${\mathcal{J}}$ by 
    \[

e^{\beta }
{\mathcal{J}}
e^{-\beta }
= \begin{pmatrix}
        A+\beta  \omega   & \pi -A\beta  -\beta  A^*-\beta  \omega \beta   \\ \omega & -A^*-\omega \beta  \end{pmatrix}. \hfill\qedhere
    \]
\end{enumerate}

\label{proposition:B_then_beta_eventype}
    Let ${\mathcal{J}}\in\mathcal{GC}_V$ be a GC structure of even cotype. 
    \begin{enumerate}
        \item There exist $B\in\scalebox{1.2}{$\wedge$}^2V^*, \beta\in\scalebox{1.2}{$\wedge$}^2 V$ and $J\in\mathcal C_V$, such that 
        \[
        {\mathcal{J}} = 
e^{\beta }

e^{B }
{\mathcal{J}}_J 
e^{-B }

e^{-\beta }
.
        \]
        \item There exist $B\in\scalebox{1.2}{$\wedge$}^2V^*, \beta\in\scalebox{1.2}{$\wedge$}^2 V$ and $J\in\mathcal C_V$, such that 
        \[
        {\mathcal{J}} =  
e^{B }

e^{\beta }
{\mathcal{J}}_J
e^{-\beta }

e^{-B }
.
        \]
    \end{enumerate}

Suppose $J,J'\in \mathcal{C}_V$ are complex structures and $\omega,\omega'\in\scalebox{1.2}{$\wedge$}^2V^*$ are symplectic forms. Then for any $B\in \scalebox{1.2}{$\wedge$}^2V^*,\beta\in\scalebox{1.2}{$\wedge$}^2V$ we have
    \begin{enumerate}
        \item $ 
e^{B }
{\mathcal{J}}_\omega 
e^{-B }
 = {\mathcal{J}}_{\omega'}$ if and only if $B=0$ and $\omega=\omega'$.
        \item $ 
e^{B }
{\mathcal{J}}_J 
e^{-B }
 = {\mathcal{J}}_{J'}$ if and only if  $J=J'$ and $B\in\scalebox{1.2}{$\wedge$}^{1,1}_JV^*$.
        \item $
e^{\beta }
{\mathcal{J}}_J 
e^{-\beta }
= {\mathcal{J}}_{J'}$ if and only if $J=J'$ and $\beta\in\scalebox{1.2}{$\wedge$}^{1,1}_JV$.
        \item $
e^{\beta }
{\mathcal{J}}_\omega
e^{-\beta }
 = {\mathcal{J}}_{\omega'}$ if and only if $\beta=0$ and $\omega=\omega'$.
    \end{enumerate}
    In particular: If the equation 
    \[

e^{\beta }

e^{B }
{\mathcal{J}}_\omega 
e^{-B }

e^{-\beta }
  = {\mathcal{J}}_J
    \]
    admits a solution $(B,\beta)$, then $B$ is unique and $\beta$ is unique up to addition of a bivector of type $(1,1)$ and if the equation 
    \[

e^{\beta }

e^{B }
{\mathcal{J}}_J  
e^{-B }

e^{-\beta }
 = {\mathcal{J}}_\omega
    \]
    admits a solution $(B,\beta)$, then $\beta$ is unique and $B$ is unique up to addition of a form of type $(1,1)$.

\label{proposition:betaBJomega}
Let $\omega\in\scalebox{1.2}{$\wedge$}^2V^*$ be a symplectic form and let $J\in \mathcal{C}_V$ be a complex structure on $V$.
\begin{enumerate}
\item The equation
\[
e^{\beta }

e^{B }
{\mathcal{J}}_\omega 
e^{-B }

e^{-\beta }
= {\mathcal{J}}_J\]
admits a solution $(B,\beta)\in \scalebox{1.2}{$\wedge$}^2V^*\times\scalebox{1.2}{$\wedge$}^2V$ if and only if $\omega\in (\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap\scalebox{1.2}{$\wedge$}^2V^*$. In this case $B$ lies in the subspace $(\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap\scalebox{1.2}{$\wedge$}^2V^*$ and is uniquely determined by 
\[B  = \omega  J.\] 
The general form of $\beta$ is 
\[\beta   = -\frac{1}{2} B^{-1} + \tau\] 
for an arbitrary $\tau\in\scalebox{1.2}{$\wedge$}^{1,1}_JV$.
\item The equation
\[
e^{\beta }

e^{B }
{\mathcal{J}}_J 
e^{-B }

e^{-\beta }
= {\mathcal{J}}_\omega\]
admits a solution $(B,\beta)\in \scalebox{1.2}{$\wedge$}^2V^*\times\scalebox{1.2}{$\wedge$}^2V$ if and only if $\omega\in (\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap\scalebox{1.2}{$\wedge$}^2V^*$. In this case $\beta$ lies in the subspace $(\scalebox{1.2}{$\wedge$}^{2,0}_JV+\scalebox{1.2}{$\wedge$}^{0,2}_JV)\cap\scalebox{1.2}{$\wedge$}^2V$ and is uniquely determined by 
\[\beta  = -J \omega^{-1} = (\omega  J)^{-1}.\] 
The general form of $B\in\scalebox{1.2}{$\wedge$}^2V^*$ is 
\[B   = -\frac{1}{2} \beta^{-1}+ B \] 
for an arbitrary $b\in\scalebox{1.2}{$\wedge$}^{1,1}_JV^*$.
\end{enumerate}

\begin{enumerate}
\item Remark \ref{remark:AdBbeta} implies in particular for a symplectic form $\omega\in \scalebox{1.2}{$\wedge$}^2V^*$: 
\begin{align*}
    & 
e^{\beta }

e^{B }
{\mathcal{J}}_\omega  
e^{-B }

e^{-\beta }
 = 
e^{\beta }
\begin{pmatrix}
    \omega^{-1} B  & -\omega^{-1} \\ \omega +B \omega^{-1} B  & -B \omega^{-1}\end{pmatrix}
e^{-\beta }
\\
    &=  \begin{pmatrix}
    \omega^{-1} B  +\beta (\omega +B  \omega^{-1} B  ) & -\omega^{-1}-\omega^{-1} B  \beta  -\beta  B  \omega^{-1}-\beta  (\omega +B  \omega^{-1} B  )\beta   \\ \omega +B  \omega^{-1} B  & -B  \omega^{-1}-(\omega +B  \omega^{-1} B  )\beta  \end{pmatrix}
\end{align*}
It follows that the equation
\[ 
e^{\beta }

e^{B }
{\mathcal{J}}_\omega  
e^{-B }

e^{-\beta }
  = {\mathcal{J}}_{J}\quad \text{for some } J\in \mathcal{C}_V\]
is equivalent to the following conditions: 
\begin{align}
    0&= \omega +B \omega^{-1}B  \label{eq:1}\\
    0&= \omega^{-1}+\omega^{-1} B\beta +\beta B\omega^{-1}+\beta (\omega+B\omega^{-1} B)\beta \label{eq:2}. 
\end{align}
If these are satisfied, then 
\[
e^{\beta}

e^{B}
{\mathcal{J}}_\omega  
e^{-B}

e^{-\beta}
 = \begin{pmatrix}
    \omega^{-1} B & 0 \\ 0 & -B\omega^{-1} \end{pmatrix}.\]
In particular
\[J := \omega^{-1} B,\] 
is a complex structure on $V$ and satisfies
\[J^2 = -1,\quad J^* = B\omega^{-1}\]
and
\[B = \omega J.\]
Note that for this to be a two-form, i.e. $B^* = - B$, we must require 
\[
-\omega  J = (\omega  J)^* = J^*\omega^* = -J^*\omega ,
\]
i.e. 
\[
J^*\omega  J = -\omega , 
\]
which implies that also 
\[J^*B  J=-B .\] 
In particular, 
\[B,\omega \in (\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap \scalebox{1.2}{$\wedge$}^2V^*.\]
Note that if \eqref{eq:1} holds, then \eqref{eq:2} simplifies to 
\[0 = \omega^{-1}+\omega^{-1}B \beta +\beta  B \omega^{-1}.\]
With the above notation, \eqref{eq:2} becomes
\[\omega^{-1} = -J\beta  -\beta  J^*,\]
which we may rewrite in the form 
\[J B^{-1} = -J\beta  -\beta  J^*,\]
or, after multiplying both sides by $-J = J^{-1}$ from the left,
\[ B^{-1} = -\beta +J\beta  J^*.\]
In other words, we see that $B\in (\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap \scalebox{1.2}{$\wedge$}^2V^*$ is non-degenerate and $- B^{-1}$ is given by (two times) the component of $\beta$ in $(\scalebox{1.2}{$\wedge$}^{2,0}_JV+\scalebox{1.2}{$\wedge$}^{0,2}_JV)\cap \scalebox{1.2}{$\wedge$}^2V$ , which is given by
\[\beta^{(2,0)}+\beta^{(0,2)} = \frac{1}{2}(\beta -J\beta  J^*).\]
\item Remark \ref{remark:AdBbeta} implies in particular
\begin{align*}
    &
e^{\beta }

e^{B }
{\mathcal{J}}_J 
e^{-B }

e^{-\beta }
= 
e^{\beta }
\begin{pmatrix}
    J & 0 \\ B  J+J^*B  & -J^*\end{pmatrix}
e^{-\beta }
\\
    &=  \begin{pmatrix}
    J + \beta(B  J+J^*B  ) & -J\beta-\beta J^*-\beta(B  J+J^*B  )\beta \\ B  J+J^*B   & -J^*-(B  J+J^*B  )\beta\end{pmatrix}
\end{align*}
It follows that 
\[
e^{\beta }

e^{B }
  {\mathcal{J}}_{J} 
e^{-B  }

e^{-\beta }
 = {\mathcal{J}}_\omega\]
for some nondegenerate $\omega\in\scalebox{1.2}{$\wedge$}^2V^*$ is equivalent to the equation
\begin{align}
    0&= J + \beta  (B  J+J^*B  ) \label{eq:3}
\end{align}
If this equation is satisfied, then 
\[
e^{\beta }

e^{B }
  {\mathcal{J}}_{J} 
e^{-B  }

e^{-\beta }
 = \begin{pmatrix}
   0& -J\beta -\beta  J^*-\beta (B  J+J^*B  )\beta  \\ B  J+J^*B   & 0 \end{pmatrix}.\]
Equating this with ${\mathcal{J}}_\omega$ and looking at the lower left entry, we find
\begin{equation}\label{eq:5}
\omega  = B  J+J^*B   \in(\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap \scalebox{1.2}{$\wedge$}^2V^*.
\end{equation}
It follows that 
\[-B  +J^*B  J = \omega  J.\]
The left hand side of this equation is (minus two times) the projection of $B$ onto the subspace $(\scalebox{1.2}{$\wedge$}^{2,0}_JV^*+\scalebox{1.2}{$\wedge$}^{0,2}_JV^*)\cap \scalebox{1.2}{$\wedge$}^2V^*$. And we see that we are free to add to $B$ any two-form $b\in\scalebox{1.2}{$\wedge$}^{1,1}_JV^*$. 

Inserting \eqref{eq:5}  into \eqref{eq:3}, we get
\[0 = J+\beta \omega ,\]
i.e.
\[\beta  = -J\omega^{-1}. \hfill \qedhere\]
\end{enumerate}

\label{proposition:Bbetaomeganeven}
    Let $V$ be a real vector space of dimension $2n$.
    \begin{enumerate}
        \item Let $\omega\in\scalebox{1.2}{$\wedge$}^2V^*$ be a symplectic form. Then there exists a complex structure $J\in \mathcal{C}_V$, a $2$-form $B\in\scalebox{1.2}{$\wedge$}^2V^*$ and a bivector $\beta\in\scalebox{1.2}{$\wedge$}^2V$ such that 

        \[
e^{\beta }

e^{B }
  {\mathcal{J}}_{\omega} 
e^{-B  }

e^{-\beta }
= {\mathcal{J}}_J\]
        if and only if $n$ is even, i.e. $\dim V$ is divisible by $4$.
        \item Let $J\in\mathcal C_V$ be a complex structure. Then there exists a symplectic form $\omega\in\scalebox{1.2}{$\wedge$}^2V^*$, a $2$-form $B\in\scalebox{1.2}{$\wedge$}^2V^*$ and a bivector $\beta\in\scalebox{1.2}{$\wedge$}^2V$ such that 
    \[
e^{\beta }

e^{B }
  {\mathcal{J}}_{J} 
e^{-B  }

e^{-\beta }
= {\mathcal{J}}_\omega\]
    if and only if $n$ is even, i.e. $\dim V$ is divisible by $4$.
    \end{enumerate}

\begin{enumerate}
    \item By the generalized Darboux theorem, we can find $\tilde{B}\in\scalebox{1.2}{$\wedge$}^2V^*$ and a splitting $ V= V_1\oplus V_2$, a complex structure $J_1\in\mathcal C_{V_1}$ and a symplectic form $\omega_2\in\scalebox{1.2}{$\wedge$}^2 V_2^*$ such that 
        \[

e^{\tilde{B} }
{\mathcal{J}} 
e^{-\tilde{B} }
 = {\mathcal{J}}_{J_1}\oplus {\mathcal{J}}_{\omega_2}.
        \]
    Since the cotype of ${\mathcal{J}}$ is even, it follows that the complex dimension of $V_2$ is even and therefore
    Proposition \ref{proposition:Bbetaomeganeven}  allows us to find $B_2\in\scalebox{1.2}{$\wedge$}^2 V_2^*, \beta_2\in \scalebox{1.2}{$\wedge$}^2 V_2$ and $J_2\in\mathcal C_{V_2}$ such that  
    \[
        {\mathcal{J}}_{\omega_2}=  
e^{B _2}

e^{\beta_2 }
{\mathcal{J}}_{J_2}
e^{-\beta_2 }

e^{-B _2}
\in\mathcal{GC}_{V_2}. 
    \]
    Using the splitting $V = V_1\oplus V_2$ and extending by zero on $V_2$, respectively $V_2^*$, we may view $B _2,\beta_2 $ as elements of $\mathfrak{so}(\mathbb{V})$. With this interpretation we can write 
    \[
    {\mathcal{J}} =  
e^{-\tilde{B}  +B _2}

e^{\beta_2 }
{\mathcal{J}}_{J_1\oplus J_2}
e^{-\beta_2 }

e^{\tilde{B} -B_2 }
.
    \] 
    \item Exchanging the role of $V$ and $V^*$ in the generalized Darboux theorem, we see that there also exists $\tilde{\beta} \in\scalebox{1.2}{$\wedge$}^2V$ such that 
     \[

e^{\tilde{\beta} }
{\mathcal{J}}
e^{-\tilde{\beta} }
 = {\mathcal{J}}_{J_1}\oplus {\mathcal{J}}_{\omega_2}.
    \]
    Note that although $\beta$-transforms do not preserve the cotype in general, they still preserve the \emph{parity} of the cotype (see \cite{Gualtieri:2003dx}).\hfill\qedhere
\end{enumerate}

\label{example:Hyperkähler}
 Suppose $\dim V = 4n$ for some $n\in\mathbb N$. Consider a (pseudo-)Hyperk\"ahler structure $(g,I,J,K)$ on $V$, i.e. $g$ is a (possibly indefinite) inner product on $V$ and $I,J,K\in\mathcal{C}_V$ are skew-symmetric with respect to $g$  and satisfy the quaternionic relations. Denote by 
\[
    \omega _I = g  I,\quad \omega_J  = g  J,\quad \omega_K  = g  K
\]
the associated symplectic forms. The quaternionic relations imply $\omega_J,\omega_K \in \scalebox{1.2}{$\wedge$}^{2,0}_IV^*+\scalebox{1.2}{$\wedge$}^{0,2}_IV^*$ and moreover 
\[
    \omega_K  I= g  KI = g  J = \omega_J .
\]
It then follows from Proposition   \ref{proposition:betaBJomega} that
        \begin{equation}
            {\mathcal{J}}_{\omega_J} = 
e^{-\omega_K^{-1}}

e^{\frac{\omega _K}{2}}
{\mathcal{J}}_I 
e^{\frac{-\omega _K}{2}}

e^{\omega_K^{-1}}
.\hfill\qedhere
        \end{equation}

Let $M$ and $\tilde{M}$ be principal $T^k$-bundles with base $B$. Consider the fiber-product $M\times_B \tilde{M}$, and the following diagram: 
\begin{center}
\begin{tikzcd}
& M\times_B \tilde{M} \ar[ld,"p"],\arrow{rd}[swap]{\tilde{p}} &\\
M \ar[rd,"\pi"] & & \tilde{M} \arrow{ld}[swap]{\tilde{\pi}}\\
& B & 
\end{tikzcd}
\end{center}
We say that $M$ and $\tilde{M}$ are \emph{T-dual} if there exists a closed $T^{2k}$-invariant two-form $F \in \Omega^2_{T^{2k}}(M\times_B\tilde{M})$ such that
the restriction
\begin{equation*}
F \colon \mathfrak{t}_M \times \mathfrak{t}_{\tilde{M}} \rightarrow \mathbb{R},
\end{equation*}
where $\mathfrak{t}_M,\mathfrak{t}_{\tilde{M}}$ denotes the tangent space to the fibres of $p$, $\tilde{p}$ respectively, is non-degenerate. We call $M \times_B \tilde{M}$ the \emph{correspondence space}.

\label{theorem:courantiso}
If $M$ and $\tilde{M}$ are T-dual, then there is an isomorphism of Courant algebroids
\begin{equation*}
\varphi \colon (TM \oplus T^*M)/T^k \rightarrow (T\tilde{M} \oplus T^*\tilde{M})/T^k.
\end{equation*}
Moreover, if ${\mathcal{J}}$ is a $T^k$-invariant GC structure on $M$ it gets transformed to a $T^k$-invariant GC structure on $\tilde{M}$ denoted $\tilde{{\mathcal{J}}}$.

\label{remark:typechange}
Given a GC structure ${\mathcal{J}}$ on $M$ there are several ways in which one my predict the type of the T-dual structure $\tilde{{\mathcal{J}}}$. This is carefully described in Example 4.3 in \cite{CG11}. For us it's important to remark that when $k=1$, one has the relation that
\begin{equation*}
    \operatorname{type}(\tilde{{\mathcal{J}}}) \pm 1
\end{equation*}
implying that the parity will always change when performing T-duality along the circle.

\label{lemma:Tdualflip}
    Let 
    \[
    L_{{\mathcal{J}}} = 
e^{\beta }

e^{B }
 L_{{\mathcal{J}}_I}
    \] 
    be a GC structure on $V/\Gamma$ and 
    \[
    L_{{\mathcal{J}}'} = 
e^{\tilde{\beta} }

e^{\tilde{B} }
L_{{\mathcal{J}}_{\tilde I}}
    \]
    a GC structure on $V^* / \Gamma^*$.
    Then $\tilde{{\mathcal{J}}} = {\mathcal{J}}'$ if and only if \begin{align*}
        &\tilde I(1-\tilde{\beta}  \beta ) = -(1-\tilde{\beta}  \beta ) I^* \\
        &(B  I + I^* B ) (1 - \beta  \tilde{\beta} ) = I^* \tilde{\beta}  - \tilde{\beta}  \tilde I^* \\
        & (\tilde{B}  \tilde I + \tilde I^* \tilde{B} ) (1-\tilde{\beta}  \beta ) = \tilde I^* \beta  - \beta  I^*
    \end{align*}
    In particular, if $\alpha^{-1} := (1-\tilde{\beta}  \beta )$ is invertible, then $\tilde{{\mathcal{J}}} = {\mathcal{J}}'$ if and only if
    \begin{align}
        &\tilde I = -\alpha^{-1} I^* \alpha \nonumber \\
        & B^{(0,2)_I} = (\tilde{\beta}  \alpha^*)^{(0,2)_I} \label{equation:Poissongauge1} \\
        & \tilde{B} ^{(0,2)_{\tilde I}} = ( \beta  \alpha)^{(0,2)_{\tilde I}}.\label{equation:Poissongauge2}
    \end{align}

    \begin{proof}
        We compute ${\mathcal{J}}$:
        \begin{align*}
            {\mathcal{J}} &=
e^{\beta }

e^{B }
 \begin{pmatrix}
                I & 0 \\ 0 &-I^* 
            \end{pmatrix}  
e^{-B }

e^{-\beta }

            \\&= \begin{pmatrix}
    I + \beta (B  I+I^*B  ) & -I\beta -\beta  I^*-\beta (B  I+I^*B  )\beta  \\ B  I+I^*B   & -I^*-(B  I+I^*B  )\beta \end{pmatrix}
    \end{align*}
    Hence
    \begin{align*}
      \tilde{{\mathcal{J}}} = \begin{pmatrix}
        -I^*-(B  I+I^*B  )\beta  & B  I+I^*B  \\
        -I\beta -\beta  I^*-\beta (B  I+I^*B  )\beta  & I + \beta (B  I+I^*B  )
    \end{pmatrix}
    \end{align*}
    needs to be equal to 
    \begin{align*}
        {\mathcal{J}}' = 
        \begin{pmatrix}
            \tilde I + \tilde{\beta} (\tilde{B}  \tilde I+\tilde I^* \tilde{B}  ) & -\tilde I \tilde{\beta} -\tilde{\beta}  \tilde I^*-\tilde{\beta} (\tilde{B}  \tilde I+\tilde I^*\tilde{B}  )\tilde{\beta}  \\ \tilde{B}  \tilde I+\tilde I^* \tilde{B}   & -\tilde I^*-(\tilde{B}  \tilde I+\tilde I^* \tilde{B}  )\tilde{\beta} \end{pmatrix}.
    \end{align*}
    Let us assume that ${\mathcal{J}}' = \tilde{{\mathcal{J}}}$. We define 
    \[
    B'  := B  I + I^* B 
    \]
    and 
    \[
    \tilde{B}'  := \tilde{B}  \tilde I + \tilde I^* \tilde{B} .
    \]
    By comparing top-left and top-right entries, we obtain
    \begin{align*}
        B'  &= -(\tilde I \tilde{\beta} +\tilde{\beta}  \tilde I^* + \tilde{\beta}  \tilde{B}'  \tilde{\beta} ) \\ 
        &= -(\tilde I + \tilde{\beta}  \tilde{B}' ) \tilde{\beta}  - \tilde{\beta}  \tilde I^* \\
        &= (I^* + B'  \beta ) \tilde{\beta} - \tilde{\beta}  \tilde I^*, 
    \end{align*}
    which implies 
    \begin{equation}\label{equation:t1}
        B'  (1 - \beta  \tilde{\beta} ) = I^* \tilde{\beta}  - \tilde{\beta}  \tilde I^*.
    \end{equation}
    Similarly, we find 
    \begin{align}
        \label{equation:t2}
        \tilde{B}'  (1-\tilde{\beta}  \beta ) = \tilde I^* \beta  - \beta  I^*.
    \end{align}
    Now compose top-left entries from the right with $(1-\tilde{\beta}  \beta )$ to get 
    \[
        (\tilde I + \tilde{\beta}  \tilde{B}' ) (1-\tilde{\beta}  \beta ) = -(I^* +  B' \beta ) (1-\tilde{\beta}  \beta )\]
     and use the identities \eqref{equation:t1} and \eqref{equation:t2} to obtain
    \[   \tilde I(1-\tilde{\beta}  \beta ) = -(1-\tilde{\beta}  \beta ) I^*.\]
    The remaining statements follow similarly.
    \end{proof}

We compute ${\mathcal{J}}$:
        \begin{align*}
            {\mathcal{J}} &=
e^{\beta }

e^{B }
 \begin{pmatrix}
                I & 0 \\ 0 &-I^* 
            \end{pmatrix}  
e^{-B }

e^{-\beta }

            \\&= \begin{pmatrix}
    I + \beta (B  I+I^*B  ) & -I\beta -\beta  I^*-\beta (B  I+I^*B  )\beta  \\ B  I+I^*B   & -I^*-(B  I+I^*B  )\beta \end{pmatrix}
    \end{align*}
    Hence
    \begin{align*}
      \tilde{{\mathcal{J}}} = \begin{pmatrix}
        -I^*-(B  I+I^*B  )\beta  & B  I+I^*B  \\
        -I\beta -\beta  I^*-\beta (B  I+I^*B  )\beta  & I + \beta (B  I+I^*B  )
    \end{pmatrix}
    \end{align*}
    needs to be equal to 
    \begin{align*}
        {\mathcal{J}}' = 
        \begin{pmatrix}
            \tilde I + \tilde{\beta} (\tilde{B}  \tilde I+\tilde I^* \tilde{B}  ) & -\tilde I \tilde{\beta} -\tilde{\beta}  \tilde I^*-\tilde{\beta} (\tilde{B}  \tilde I+\tilde I^*\tilde{B}  )\tilde{\beta}  \\ \tilde{B}  \tilde I+\tilde I^* \tilde{B}   & -\tilde I^*-(\tilde{B}  \tilde I+\tilde I^* \tilde{B}  )\tilde{\beta} \end{pmatrix}.
    \end{align*}
    Let us assume that ${\mathcal{J}}' = \tilde{{\mathcal{J}}}$. We define 
    \[
    B'  := B  I + I^* B 
    \]
    and 
    \[
    \tilde{B}'  := \tilde{B}  \tilde I + \tilde I^* \tilde{B} .
    \]
    By comparing top-left and top-right entries, we obtain
    \begin{align*}
        B'  &= -(\tilde I \tilde{\beta} +\tilde{\beta}  \tilde I^* + \tilde{\beta}  \tilde{B}'  \tilde{\beta} ) \\ 
        &= -(\tilde I + \tilde{\beta}  \tilde{B}' ) \tilde{\beta}  - \tilde{\beta}  \tilde I^* \\
        &= (I^* + B'  \beta ) \tilde{\beta} - \tilde{\beta}  \tilde I^*, 
    \end{align*}
    which implies 
    \begin{equation}\label{equation:t1}
        B'  (1 - \beta  \tilde{\beta} ) = I^* \tilde{\beta}  - \tilde{\beta}  \tilde I^*.
    \end{equation}
    Similarly, we find 
    \begin{align}
        \label{equation:t2}
        \tilde{B}'  (1-\tilde{\beta}  \beta ) = \tilde I^* \beta  - \beta  I^*.
    \end{align}
    Now compose top-left entries from the right with $(1-\tilde{\beta}  \beta )$ to get 
    \[
        (\tilde I + \tilde{\beta}  \tilde{B}' ) (1-\tilde{\beta}  \beta ) = -(I^* +  B' \beta ) (1-\tilde{\beta}  \beta )\]
     and use the identities \eqref{equation:t1} and \eqref{equation:t2} to obtain
    \[   \tilde I(1-\tilde{\beta}  \beta ) = -(1-\tilde{\beta}  \beta ) I^*.\]
    The remaining statements follow similarly.

In the case where $(1-\tilde{\beta} \beta )$ is invertible, there is a Poisson geometric interpretation of the equations \eqref{equation:Poissongauge1} and \eqref{equation:Poissongauge2}.

Given two Poisson structures $\pi,\pi'$ on $M$, they are said to be \emph{gauge equivalent} if there exists a closed two-form $B$ such that $(\mathrm{id}+\pi B )$ is invertible and satisfies the equation:
\begin{equation*}
\pi'  = \pi (1+\pi B )^{-1}.    
\end{equation*}
Given a Poisson structure $\pi$ it's graph $L_{\pi} = {\rm graph }(\pi) \subset TM \oplus T^*M$ defines a Dirac structure. The term gauge equivalence comes from the fact the associated Dirac structures are related via $L_{\pi'} =  
e^{B }
 L_{\pi}$.

If we view $B$ as a bivector on $V^*$ and $\beta$ as a two-form on $V^*$, then the equation \eqref{equation:Poissongauge1} tells us precisely that $\tilde{\beta}$ is the $\beta$-gauge transformation of $B$. Similarly, \eqref{equation:Poissongauge2} tells us that $\beta$ is the $B$-gauge of $\tilde{\beta}$.

