where 
\begin{equation} \label{eq:starformula} (u_{\gamma_1} \otimes \omega_1) \star^{\beta} (u_{\gamma_2} \otimes \omega_2) := e^{\pi \mathbf{i} \beta(\gamma_1,\gamma_2)} u_{\gamma_1 + \gamma_2} \otimes \omega_1 \wedge \omega_2\end{equation}
    for $u_{\gamma}(x) := e^{2 \pi \mathbf{i} \gamma(x)}$, $\gamma \in \Gamma^*$ and $\omega_i \in \scalebox{1.2}{$\wedge$}^{(0,\bullet)} V_{\mathbb C}^*$.

